SubProceso ChargeWithVat(total Como Entero Por Referencia)
  total <- total + total * 18 div 100;
  total <- total - total div 10;
  Escribir "Total: ", total;
FinSubProceso

Algoritmo Till
  Definir purchase Como Entero;
  Leer purchase;
  ChargeWithVat(purchase);
FinAlgoritmo

